// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Layout, MatrixTriangle } from '@stdlib/types/blas';

/**
* Specifies the norm type: 'M' (max abs), '1'/'O' (one-norm), 'I' (infinity-norm), 'F'/'E' (Frobenius).
*/
type Norm = 'M' | 'm' | '1' | 'O' | 'o' | 'I' | 'i' | 'F' | 'f' | 'E' | 'e';

/**
* Interface describing `dlansy`.
*/
interface Routine {
	/**
	* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix `A`.
	*
	* @param order - storage layout of `A`
	* @param norm - specifies the norm type
	* @param uplo - specifies whether the upper or lower triangular part of `A` is referenced
	* @param N - order of the matrix `A`
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @returns matrix norm
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
	*
	* var v = dlansy( 'row-major', 'M', 'upper', 2, A, 2 );
	* // returns 5.0
	*/
	( order: Layout, norm: Norm, uplo: MatrixTriangle, N: number, A: Float64Array, LDA: number ): number;

	/**
	* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix `A` using alternative indexing semantics.
	*
	* @param norm - specifies the norm type
	* @param uplo - specifies whether the upper or lower triangular part of `A` is referenced
	* @param N - order of the matrix `A`
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @returns matrix norm
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
	*
	* var v = dlansy.ndarray( 'M', 'upper', 2, A, 2, 1, 0 );
	* // returns 5.0
	*/
	ndarray( norm: Norm, uplo: MatrixTriangle, N: number, A: Float64Array, strideA1: number, strideA2: number, offsetA: number ): number;
}

/**
* Returns the value of the one-norm, Frobenius norm, infinity-norm, or the largest absolute value of any element of a real symmetric matrix `A`.
*
* @param order - storage layout of `A`
* @param norm - specifies the norm type
* @param uplo - specifies whether the upper or lower triangular part of `A` is referenced
* @param N - order of the matrix `A`
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @returns matrix norm
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
*
* var v = dlansy( 'row-major', 'M', 'upper', 2, A, 2 );
* // returns 5.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 2.0, 2.0, 5.0 ] );
*
* var v = dlansy.ndarray( 'M', 'upper', 2, A, 2, 1, 0 );
* // returns 5.0
*/
declare var dlansy: Routine;


// EXPORTS //

export = dlansy;
